import 'package:characters/characters.dart';

// Small API examples. For full API docs see:
// https://pub.dev/documentation/characters/latest/characters/characters-library.html
void main() {
  var hi = 'Hi 🇩🇰';
  print('String is "$hi"\n');

  // Length.
  print('String.length: ${hi.length}');
  print('Characters.length: ${hi.characters.length}\n');

  // Last character.
  print('The string ends with: ${hi.substring(hi.length - 1)}');
  print('The last character: ${hi.characters.last}\n');

  // Skip last character.
  print('Substring -1: "${hi.substring(0, hi.length - 1)}"');
  print('Skipping last character: "${hi.characters.skipLast(1)}"\n');

  // Replace characters.
  var newHi = hi.characters.replaceAll('🇩🇰'.characters, '🇺🇸'.characters);
  print('Change flag: "$newHi"');
}

/// Prints currency exchange table using www.floatrates.com.
library;

import 'dart:convert';
import 'dart:io';

import 'package:xml/xml.dart';

final HttpClient httpClient = HttpClient();

void writeCell([Object? output]) {
  final contents = output?.toString() ?? '';
  stdout.write(contents.padLeft(14, ' '));
  stdout.write('  ');
}

Future<void> main(List<String> arguments) async {
  if (arguments.isEmpty) {
    stdout.writeln('Example: currencies EUR CHF ...');
    exit(1);
  }
  final currencies = arguments
      .map((argument) => argument.trim().toLowerCase())
      .toSet();
  writeCell();
  currencies.forEach(writeCell);
  stdout.writeln();
  for (final sourceCurrency in currencies) {
    final url = 'https://www.floatrates.com/daily/$sourceCurrency.xml';
    final request = await httpClient.getUrl(Uri.parse(url));
    final response = await request.close();
    final stream = response.transform(utf8.decoder);
    final contents = await stream.join();
    final document = XmlDocument.parse(contents);
    writeCell(sourceCurrency);
    for (final targetCurrency in currencies) {
      if (sourceCurrency == targetCurrency) {
        writeCell();
      } else {
        writeCell(
          document.rootElement
              .findElements('item')
              .where(
                (item) => item
                    .findElements('targetCurrency')
                    .any(
                      (element) =>
                          element.innerText.toLowerCase() == targetCurrency,
                    ),
              )
              .first
              .findElements('exchangeRate')
              .first
              .innerText,
        );
      }
    }
    stdout.writeln();
  }
}

