import 'package:code_builder/code_builder.dart';
import 'package:dart_style/dart_style.dart';

final _dartfmt = DartFormatter(
  languageVersion: DartFormatter.latestLanguageVersion,
);

void main() {
  print('animalClass():\n${'=' * 40}\n${animalClass()}');
  print('scopedLibrary():\n${'=' * 40}\n${scopedLibrary()}');
  print('jsonEnum():\n${'=' * 40}\n${jsonEnum()}');
}

/// Outputs:
///
/// ```dart
/// class Animal extends Organism {
///   void eat() => print('Yum!');
/// }
/// ```
String animalClass() {
  final animal = Class(
    (b) =>
        b
          ..name = 'Animal'
          ..extend = refer('Organism')
          ..methods.add(
            Method.returnsVoid(
              (b) =>
                  b
                    ..name = 'eat'
                    ..body = refer('print').call([literalString('Yum!')]).code,
            ),
          ),
  );
  return _dartfmt.format('${animal.accept(DartEmitter())}');
}

/// Outputs:
///
/// ```dart
/// import 'package:a/a.dart' as _i1;
/// import 'package:b/b.dart' as _i2;
///
/// _i1.Thing doThing() {}
/// _i2.Other doOther() {}
/// ```
String scopedLibrary() {
  final methods = [
    Method(
      (b) =>
          b
            ..body = const Code('')
            ..name = 'doThing'
            ..returns = refer('Thing', 'package:a/a.dart'),
    ),
    Method(
      (b) =>
          b
            ..body = const Code('')
            ..name = 'doOther'
            ..returns = refer('Other', 'package:b/b.dart'),
    ),
  ];
  final library = Library((b) => b.body.addAll(methods));
  return _dartfmt.format('${library.accept(DartEmitter.scoped())}');
}

/// Outputs:
///
/// ```dart
/// enum Unit {
///  @JsonKey('m')
///  metric,
///  @JsonKey('i')
///  imperial
/// }
/// ```
String jsonEnum() {
  final values = <EnumValue>[
    EnumValue(
      (b) =>
          b
            ..name = 'metric'
            ..annotations.addAll([
              refer('JsonKey').call([literalString('m')]),
            ]),
    ),
    EnumValue(
      (b) =>
          b
            ..name = 'imperial'
            ..annotations.addAll([
              refer('JsonKey').call([literalString('i')]),
            ]),
    ),
  ];
  final e = Enum(
    (b) =>
        b
          ..name = 'Unit'
          ..values.addAll(values),
  );
  return _dartfmt.format('${e.accept(DartEmitter())}');
}

// ignore_for_file: avoid_print, prefer_file_naming_conventions
import 'package:bloc/bloc.dart';
import 'package:bloc_concurrency/bloc_concurrency.dart';

Future<void> tick() => Future<void>.delayed(Duration.zero);

Future<void> main() async {
  /// Create a `CounterBloc` instance.
  final bloc = CounterBloc();

  /// Subscribe to state changes and print each state.
  final subscription = bloc.stream.listen(print);

  /// Interact with the `bloc` to trigger `state` changes.
  bloc.add(CounterIncrementPressed());
  await tick();
  bloc.add(CounterIncrementPressed());
  await tick();
  bloc.add(CounterIncrementPressed());
  await tick();

  /// Wait 1 second...
  await Future<void>.delayed(const Duration(seconds: 1));

  /// Close the `bloc` when it is no longer needed.
  await bloc.close();

  /// Cancel the subscription.
  await subscription.cancel();
}

/// The events which `CounterBloc` will react to.
abstract class CounterEvent {}

/// Notifies bloc to increment state.
class CounterIncrementPressed extends CounterEvent {}

/// A `CounterBloc` which handles converting `CounterEvent`s into `int`s.
class CounterBloc extends Bloc<CounterEvent, int> {
  /// The initial state of the `CounterBloc` is 0.
  CounterBloc() : super(0) {
    /// When a `CounterIncrementPressed` event is added,
    /// the current `state` of the bloc is accessed via the `state` property
    /// and a new state is emitted via `emit`.
    on<CounterIncrementPressed>(
      (event, emit) async {
        await Future<void>.delayed(const Duration(seconds: 1));
        emit(state + 1);
      },

      /// Specify a custom event transformer
      /// in this case events will be processed sequentially.
      transformer: sequential(),
    );
  }
}
